package com.carrylink.service;

import com.carrylink.api.Dtos;
import com.carrylink.domain.*;
import com.carrylink.repo.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;
import java.util.*;
import java.util.stream.Collectors;

@Service @RequiredArgsConstructor
public class CarryService {
  private final UserRepository users; private final TripRepository trips; private final DeliveryRequestRepository requests; private final BookingRepository bookings; private final PaymentRepository payments; private final ReportRepository reports; private final ChatMessageRepository messages; private final ReviewRepository reviews;
  private User current(){ return users.findByEmail(org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow(); }
  @Transactional public Trip createTrip(Dtos.CreateTrip d){ User u=current(); if(u.getRole()!=Role.TRAVELLER) throw new IllegalStateException("Only traveller accounts can publish trips"); if(!d.expectedArrivalTime().isAfter(d.departureTime())) throw new IllegalArgumentException("Expected arrival must be after departure"); Trip t=new Trip(); t.setTraveller(u); t.setOrigin(d.origin()); t.setDestination(d.destination()); t.setDepartureTime(d.departureTime()); t.setExpectedArrivalTime(d.expectedArrivalTime()); t.setTransportType(d.transportType()); t.setTotalCapacity(d.totalCapacity()); t.setAvailableCapacity(d.totalCapacity()); t.setPickupPoint(d.pickupPoint()); t.setDropPoint(d.dropPoint()); for(int i=0;i<d.stops().size();i++){ Dtos.Stop s=d.stops().get(i); TripStop stop=new TripStop(); stop.setTrip(t); stop.setLocation(s.location()); stop.setSequenceOrder(i); stop.setExpectedArrival(s.expectedArrival()); stop.setExpectedDeparture(s.expectedDeparture()); t.getStops().add(stop); } return trips.save(t); }
  @Transactional public DeliveryRequest createRequest(Dtos.CreateRequest d){ User u=current(); if(u.getRole()!=Role.SENDER) throw new IllegalStateException("Only senders can create requests"); DeliveryRequest r=new DeliveryRequest(); r.setSender(u); r.setOrigin(d.origin()); r.setDestination(d.destination()); r.setPickupPoint(d.pickupPoint()); r.setDropPoint(d.dropPoint()); r.setItemCategory(d.itemCategory()); r.setDescription(d.description()); r.setWeight(d.weight()); r.setDimensions(d.dimensions()); r.setRequiredBy(d.requiredBy()); r.setOfferedAmount(d.offeredAmount()); return requests.save(r); }
  @Transactional(readOnly = true) public List<Dtos.Match> matches(Long requestId){ DeliveryRequest r=requests.findById(requestId).orElseThrow(); if(r.getStatus()!=RequestStatus.OPEN)return List.of(); Instant now=Instant.now(); return trips.findAll().stream().filter(t->t.getStatus()==TripStatus.ACTIVE&&t.getDepartureTime().isAfter(now)&&t.getAvailableCapacity()>=r.getWeight()&&t.getDepartureTime().isBefore(r.getRequiredBy())).map(t->{ List<String> route=routeFor(t); int a=route.indexOf(normalize(r.getOrigin())), b=route.indexOf(normalize(r.getDestination())); return a>=0&&b>a?new Dtos.Match(t.getId(),t.getTraveller().getName(),t.getOrigin(),t.getDestination(),t.getAvailableCapacity(),t.getDepartureTime(),t.getExpectedArrivalTime(),b-a,t.getTransportType(),t.getPickupPoint(),t.getDropPoint(),t.getTraveller().getRating()):null; }).filter(Objects::nonNull).sorted(Comparator.comparingInt(Dtos.Match::routeScore)).toList(); }
  @Transactional public Booking book(Dtos.BookingCreate d){ User actor=current(); DeliveryRequest r=requests.findById(d.requestId()).orElseThrow(); if(bookings.findByRequestId(r.getId()).isPresent()) throw new IllegalStateException("This delivery already has a booking. Open the delivery room to view it."); Trip t=trips.findLockedById(d.tripId()).orElseThrow(); boolean senderOwnsRequest=r.getSender().getId().equals(actor.getId()); boolean travellerOwnsTrip=t.getTraveller().getId().equals(actor.getId()); if(!senderOwnsRequest&&!travellerOwnsTrip) throw new IllegalStateException("You must own the request or selected trip"); if(r.getStatus()!=RequestStatus.OPEN) throw new IllegalStateException("Request is no longer open"); if(t.getAvailableCapacity()<r.getWeight()) throw new IllegalStateException("Trip capacity changed; please choose another trip"); if(matches(r.getId()).stream().noneMatch(m->m.tripId().equals(t.getId()))) throw new IllegalStateException("Trip is not route-compatible"); Booking b=new Booking(); b.setRequest(r); b.setTrip(t); b.setSender(r.getSender()); b.setTraveller(t.getTraveller()); b.setReservedWeight(r.getWeight()); b.setProposedBy(actor.getRole()); b.setStatus(BookingStatus.PENDING); return bookings.save(b); }
  @Transactional public Booking accept(Long id){ Booking b=bookings.findById(id).orElseThrow(); User actor=current(); if(!b.getSender().getId().equals(actor.getId())&&!b.getTraveller().getId().equals(actor.getId())) throw new IllegalStateException("You are not part of this booking"); if(b.getStatus()!=BookingStatus.PENDING) throw new IllegalStateException("This proposal is no longer awaiting acceptance"); if(b.getProposedBy()==actor.getRole()) throw new IllegalStateException("The other party must accept this proposal"); Trip t=trips.findLockedById(b.getTrip().getId()).orElseThrow(); if(t.getAvailableCapacity()<b.getReservedWeight()) throw new IllegalStateException("Trip capacity changed; this package no longer fits"); t.setAvailableCapacity(t.getAvailableCapacity()-b.getReservedWeight()); if(t.getAvailableCapacity()==0)t.setStatus(TripStatus.FULL); b.getRequest().setStatus(RequestStatus.BOOKED); b.setStatus(BookingStatus.ACCEPTED); return b; }
  public List<Trip> myTrips(){return trips.findByTravellerIdOrderByDepartureTimeDesc(current().getId());}
  @Transactional(readOnly = true) public List<Dtos.TravellerTrip> availableTravellerTrips(){ if(current().getRole()!=Role.SENDER) throw new IllegalStateException("Only senders can browse traveller trips"); return trips.findAll().stream().filter(t->t.getStatus()==TripStatus.ACTIVE&&t.getAvailableCapacity()>0).map(t->new Dtos.TravellerTrip(t.getId(),t.getTraveller().getName(),t.getOrigin(),t.getDestination(),t.getAvailableCapacity(),t.getDepartureTime(),t.getExpectedArrivalTime(),t.getTransportType(),t.getPickupPoint(),t.getDropPoint(),t.getTraveller().getRating(),t.getTraveller().getCompletedTrips())).sorted(Comparator.comparing(Dtos.TravellerTrip::departureTime)).toList(); }
  public List<DeliveryRequest> myRequests(){return requests.findBySenderIdOrderByCreatedAtDesc(current().getId());}
  @Transactional(readOnly = true) public List<Dtos.MatchingRequest> matchingRequestsForTraveller(){ User traveller=current(); if(traveller.getRole()!=Role.TRAVELLER) throw new IllegalStateException("Only travellers can view matching delivery requests"); Instant now=Instant.now(); List<Trip> myTrips=trips.findByTravellerIdOrderByDepartureTimeDesc(traveller.getId()); return requests.findByStatusOrderByCreatedAtDesc(RequestStatus.OPEN).stream().map(r->myTrips.stream().filter(t->t.getStatus()==TripStatus.ACTIVE&&t.getDepartureTime().isAfter(now)&&t.getAvailableCapacity()>=r.getWeight()&&t.getDepartureTime().isBefore(r.getRequiredBy())&&routeContains(t,r)).findFirst().map(t->new Dtos.MatchingRequest(r.getId(),t.getId(),r.getSender().getName(),r.getOrigin(),r.getDestination(),r.getPickupPoint(),r.getDropPoint(),r.getDescription(),r.getWeight(),r.getDimensions(),r.getRequiredBy(),r.getOfferedAmount(),r.getStatus())).orElse(null)).filter(Objects::nonNull).toList(); }
  private boolean routeContains(Trip trip,DeliveryRequest request){ List<String> route=routeFor(trip); int origin=route.indexOf(normalize(request.getOrigin())), destination=route.indexOf(normalize(request.getDestination())); return origin>=0&&destination>origin; }
  private List<String> routeFor(Trip trip){ List<String> route=new ArrayList<>(); route.add(normalize(trip.getOrigin())); trip.getStops().stream().map(TripStop::getLocation).map(this::normalize).filter(location->!route.contains(location)).forEach(route::add); if(!route.contains(normalize(trip.getDestination())))route.add(normalize(trip.getDestination())); return route; }
  private String normalize(String location){return location.trim().toLowerCase(Locale.ROOT);}
  public List<Booking> myBookings(){User u=current();return bookings.findBySenderIdOrTravellerIdOrderByCreatedAtDesc(u.getId(),u.getId());}
  public User profile(){return current();}
  @Transactional public Booking cancel(Long id){ Booking b=bookings.findById(id).orElseThrow(); User u=current(); if(!b.getSender().getId().equals(u.getId())&&!b.getTraveller().getId().equals(u.getId())) throw new IllegalStateException("You are not part of this booking"); if(b.getStatus()!=BookingStatus.PENDING&&b.getStatus()!=BookingStatus.ACCEPTED&&b.getStatus()!=BookingStatus.PAID) throw new IllegalStateException("This delivery can no longer be cancelled"); if(b.getStatus()!=BookingStatus.PENDING){Trip t=trips.findLockedById(b.getTrip().getId()).orElseThrow();t.setAvailableCapacity(t.getAvailableCapacity()+b.getReservedWeight());if(t.getStatus()==TripStatus.FULL)t.setStatus(TripStatus.ACTIVE);} b.getRequest().setStatus(RequestStatus.CANCELLED);b.setStatus(BookingStatus.CANCELLED);return b; }
  @Transactional public Booking addDeliveryProof(Long id,Dtos.DeliveryProof proof){ Booking b=bookings.findById(id).orElseThrow(); User u=current(); if(!b.getTraveller().getId().equals(u.getId())) throw new IllegalStateException("Only the traveller can add delivery proof"); if(b.getStatus()!=BookingStatus.DELIVERED) throw new IllegalStateException("Delivery proof is available after delivery"); b.setReceiverName(proof.receiverName());b.setDeliveryNote(proof.note());b.setDeliveredAt(Instant.now());return b; }
  private Booking memberBooking(Long id){ Booking b=bookings.findById(id).orElseThrow(); User u=current(); if(!b.getSender().getId().equals(u.getId())&&!b.getTraveller().getId().equals(u.getId())) throw new IllegalStateException("You are not part of this booking"); return b; }
  public List<ChatMessage> messages(Long bookingId){memberBooking(bookingId); return messages.findByBookingIdOrderByCreatedAtAsc(bookingId);}
  @Transactional public ChatMessage message(Long bookingId,Dtos.ChatCreate input){ Booking b=memberBooking(bookingId); ChatMessage m=new ChatMessage(); m.setBooking(b); m.setSender(current()); m.setBody(input.body()); return messages.save(m); }
  @Transactional public Review review(Long bookingId,Dtos.ReviewCreate input){ Booking b=memberBooking(bookingId); if(b.getStatus()!=BookingStatus.DELIVERED) throw new IllegalStateException("Reviews are available after delivery"); User reviewer=current(); User target=b.getSender().getId().equals(reviewer.getId())?b.getTraveller():b.getSender(); if(reviews.findByBookingIdAndReviewerId(bookingId,reviewer.getId()).isPresent()) throw new IllegalStateException("You already reviewed this delivery"); Review review=new Review(); review.setBooking(b); review.setReviewer(reviewer); review.setReviewedUser(target); review.setRating(input.rating()); review.setComment(input.comment()); return reviews.save(review); }
  @Transactional public Booking changeStatus(Long id, BookingStatus status){ Booking b=bookings.findById(id).orElseThrow(); User u=current(); if(!b.getSender().getId().equals(u.getId())&&!b.getTraveller().getId().equals(u.getId())) throw new IllegalStateException("You are not part of this booking"); BookingStatus currentStatus=b.getStatus(); if(status==BookingStatus.HANDED_OVER&&(!b.getSender().getId().equals(u.getId())||currentStatus!=BookingStatus.PAID)) throw new IllegalStateException("The sender can mark the package handed over after payment"); if(status==BookingStatus.IN_TRANSIT&&(!b.getTraveller().getId().equals(u.getId())||currentStatus!=BookingStatus.HANDED_OVER)) throw new IllegalStateException("The traveller can start delivery after handover"); if(status==BookingStatus.DELIVERED&&(!b.getTraveller().getId().equals(u.getId())||currentStatus!=BookingStatus.IN_TRANSIT))throw new IllegalStateException("The traveller can mark delivery complete only after departure"); if(status==BookingStatus.CANCELLED){if(currentStatus==BookingStatus.DELIVERED||currentStatus==BookingStatus.IN_TRANSIT)throw new IllegalStateException("A delivery already in progress cannot be cancelled"); if(currentStatus!=BookingStatus.PENDING&&currentStatus!=BookingStatus.ACCEPTED&&currentStatus!=BookingStatus.PAID&&currentStatus!=BookingStatus.HANDED_OVER)throw new IllegalStateException("This booking cannot be cancelled"); if(currentStatus!=BookingStatus.PENDING){Trip t=trips.findLockedById(b.getTrip().getId()).orElseThrow();t.setAvailableCapacity(t.getAvailableCapacity()+b.getReservedWeight());if(t.getStatus()==TripStatus.FULL)t.setStatus(TripStatus.ACTIVE);} b.getRequest().setStatus(RequestStatus.CANCELLED);} else if(status!=BookingStatus.HANDED_OVER&&status!=BookingStatus.IN_TRANSIT&&status!=BookingStatus.DELIVERED) throw new IllegalStateException("Invalid delivery status transition"); b.setStatus(status); if(status==BookingStatus.IN_TRANSIT)b.getRequest().setStatus(RequestStatus.IN_TRANSIT); if(status==BookingStatus.DELIVERED)b.getRequest().setStatus(RequestStatus.DELIVERED); return b; }
  @Transactional public Payment pay(Long bookingId, Dtos.PaymentCreate input){ Booking b=bookings.findById(bookingId).orElseThrow(); User u=current(); if(!b.getSender().getId().equals(u.getId()))throw new IllegalStateException("Only the sender can pay"); if(b.getStatus()!=BookingStatus.ACCEPTED)throw new IllegalStateException("The traveller must accept the proposal before payment"); return payments.findByIdempotencyKey(input.idempotencyKey()).orElseGet(()->{Payment p=new Payment();p.setBooking(b);p.setAmount(b.getRequest().getOfferedAmount());p.setIdempotencyKey(input.idempotencyKey());p.setStatus(PaymentStatus.AUTHORIZED);p.setUpdatedAt(java.time.Instant.now());b.setStatus(BookingStatus.PAID);return payments.save(p);}); }
  @Transactional public Report report(Long bookingId,Dtos.ReportCreate input){Booking b=bookings.findById(bookingId).orElseThrow();User u=current();if(!b.getSender().getId().equals(u.getId())&&!b.getTraveller().getId().equals(u.getId()))throw new IllegalStateException("You are not part of this booking");Report r=new Report();r.setBooking(b);r.setReporter(u);r.setDescription(input.description());b.setStatus(BookingStatus.DISPUTED);b.getRequest().setStatus(RequestStatus.DISPUTED);return reports.save(r);}
  public List<Report> openReports(){if(current().getRole()!=Role.ADMIN)throw new IllegalStateException("Admin access required");return reports.findByStatusOrderByCreatedAtAsc(ReportStatus.OPEN);}
  @Transactional public Report reviewReport(Long id,ReportStatus status){if(current().getRole()!=Role.ADMIN)throw new IllegalStateException("Admin access required");Report r=reports.findById(id).orElseThrow();r.setStatus(status);return r;}
}
